module.exports = fetchBundle;

const fs = require('fs');
const path = require('path');
const request = require('request');
const Promise = require('bluebird');

function fetchBundle(uri, dir, ext, proxy) {
    ext = ext || '';
    proxy = proxy || '';
    const existingHashes = fs.readdirSync(dir).map((filename) => path.parse(filename).name);
    return getResource(uri, existingHashes, proxy)
        .then((resource) => {
            const bundlePath = path.join(dir, `${resource.etag}.${ext}`);

            if(resource.payload) fs.writeFileSync(bundlePath, resource.payload);

            return bundlePath;
        });
}

function getResource(uri, etags, proxy) {
    const options = {
        uri: uri,
        gzip: true,
        rejectUnauthorized: false,
        headers: {
            'If-None-Match': etags.join()
        },
        proxy: proxy,
        timeout: 10000
    };

    return new Promise((resolve, reject) => {
        request.get(options, (error, response, body) => {
            if(error) {
                reject(error);
                return;
            }

            if(!response.headers.etag || response.headers['content-type'] !== 'application/javascript') {
                reject('Fetching bundle error: no support.');
                return;
            }

            response.headers.etag = response.headers.etag.replace(/(^"|"$)/g, '');

            switch (response.statusCode) {
                case 200: {
                    resolve({etag: response.headers.etag, payload: body});
                } break;
                case 304: {
                    resolve({etag: response.headers.etag});
                } break;
                default:
                {
                    reject(`Fetching bundle error: response status code ${response.statusCode}.`);
                }
            }
        })
    });
}
